claims.quote:
# Prod-safe defaults: nothing is stamped or expired. Non-prod opts in by setting
  # NOTIFICATION_TTL_DAYS and NOTIFICATION_TTL_EXPIRY_ENABLED=true.
  ttl:
    days: ${NOTIFICATION_TTL_DAYS:}
    environment: ${ENVIRONMENT:local}
    expiry:
      enabled: ${NOTIFICATION_TTL_EXPIRY_ENABLED:false}
